    ["Ahem..."] = "Кхм...",
    ["<P_Heart>(Never heard of this god... and I always feel like something is wrong with this altar...)</>"] = "<P_Heart> (Я никогда не слышал об этом боге... и мне всегда кажется, что с этим алтарем что-то не так...) </>",
